mapper.select:
select f.facility_no , f.facility_ty_cd , f.instl_dt , f.facility_nm , f.apt_cmplex_no , f.dong_no , f.loc_cn , f.use_yn , f.file_group_no , cc.code_name as facility_ty_nm , case when mh.facility_no is not null then 'Y' else 'N' end as meter_linked_yn from facility f left outer join common_code cc on cc.group_code_no = 'FACILITY_TY' and cc.code_no_cd = f.facility_ty_cd
left outer join ( select distinct facility_no from meter_hstry ) mh on mh.facility_no = f.facility_no where f.facility_no = #{facilityNo}
and f.apt_cmplex_no = ( select mo.apt_cmplex_no from mgmt_office mo where mo.mgmt_ofc_no = #{mgmtOfcNo} )

select apt_cmplex_no    
from mgmt_office
where mgmt_ofc_no = #{mgmtOfcNo}

mapper.insert:
insert into facility (
facility_no       
, facility_ty_cd   
, instl_dt         
, facility_nm      
, apt_cmplex_no    
, dong_no          
, loc_cn           
, use_yn           
, file_group_no    
) values (
#{facilityNo}
, #{facilityTyCd}
, #{instlDt}
, #{facilityNm}
, #{aptCmplexNo}
, #{dongNo}
, #{locCn}
, nvl(#{useYn}, 'Y')    
, #{fileGroupNo}
)

mapper.update:
update facility
set facility_nm   = #{facilityNm}      
, instl_dt      = #{instlDt}         
, loc_cn        = #{locCn}           
, use_yn        = #{useYn}           
, file_group_no = #{fileGroupNo}     
where facility_no = #{facilityNo}

update facility
set facility_ty_cd = #{facilityTyCd}   
where facility_no  = #{facilityNo}

update facility
set use_yn = #{useYn}       
where facility_no = #{facilityNo}

mapper.select:
select (

select count(*) from facility_contract    where facility_no = #{facilityNo}
) + (

select count(*) from facility_check_hstry where facility_no = #{facilityNo}
) + (

select count(*) from meter_hstry          where facility_no = #{facilityNo}
) as linked_cnt
from dual

select *
from attach_file
where file_group_no  = #{fileGroupNo}
  and file_save_uuid = #{fileSaveUuid}

mapper.delete:
delete from attach_file
where file_group_no  = #{fileGroupNo}
  and file_save_uuid = #{fileSaveUuid}
